use common::{Handle, Outcome};
use serde_json::json;

fn project(second_start: u64, second_len: u64) -> Handle {
    Handle::from_json(
        &json!({
          "version": 2,
          "canvas": {"width": 1920, "height": 1080, "fps": [30, 1], "background": [0, 0, 0, 1],
                     "fit_new_clips": true, "timecode_frames": true},
          "media": [],
          "tracks": [{"id": 4, "name": "Track 1"}, {"id": 5, "name": "Track 2"}],
          "clips": [
            {"id": 10, "track": 4, "start": 0, "duration": 3000000,
             "source": {"kind": "text"}, "video": {}, "text": {"content": "A"}},
            {"id": 20, "track": 4, "start": second_start, "duration": second_len,
             "source": {"kind": "text"}, "video": {}, "text": {"content": "B"}}
          ],
          "next_id": 100
        })
        .to_string(),
    )
}

fn describe(h: &Handle) -> String {
    let v = h.value();
    v["clips"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| format!("#{} track {} at {}", c["id"], c["track"], c["start"]))
        .collect::<Vec<_>>()
        .join("; ")
}

