    let p = project(second_start, second_len);
    println!("--- {name}: {}", describe(&p));
    match p.try_apply(&json!({"op": "duplicate", "clips": [10]})) {
        Ok(Outcome::Applied(h)) => println!("duplicate APPLIED: {}", describe(&h)),
        Ok(Outcome::Identity) => println!("duplicate IDENTITY"),
        Ok(Outcome::Refused(why)) => {
            println!("duplicate REFUSED: {why}");
