            match p.try_apply(&json!({"op": "move_clip", "clips": [10], "delta": 6000000, "track": 5})) {
                Ok(Outcome::Applied(h)) => println!("fallback move_clip APPLIED: {}", describe(&h)),
                _ => println!("fallback move_clip did not apply"),
            }
        }
        Err(e) => println!("duplicate ERROR: {e}"),
    }
}

fn main() {
    case("abutting, neighbour same length", 3000000, 3000000);
    case("abutting, neighbour longer", 3000000, 9000000);
    case("abutting, neighbour shorter", 3000000, 600000);
    case("gap of half a clip", 4500000, 3000000);
    case("gap of 1 frame less than half... gap small", 3600000, 3000000);
    case("clear gap", 6000000, 3000000);
}

